<?php

declare(strict_types=1);

namespace App\Shared\Infrastructure\Http\Cache;

/**
 * The two caches of the store: Varnish in front of the catalog reads of the API and the ISR pages of the store. Tags
 * come from CacheTags only. Varnish always goes first, so a page regenerated by the store reads fresh data.
 */
interface StorefrontCache
{
    /**
     * Purges the tag of the product in Varnish, then revalidates it in the store: the product page and every list
     * response with the product.
     *
     * @throws StorefrontCacheFailure when either layer fails; after a failed purge the store is not called
     */
    public function invalidateProduct(string $productId): void;

    /**
     * Purges the catalog tag in Varnish: every cached catalog response.
     *
     * @throws StorefrontCacheFailure
     */
    public function purgeAll(): void;

    /**
     * Revalidates the catalog tag in the store: every ISR page. Call it after purgeAll().
     *
     * @throws StorefrontCacheFailure
     */
    public function revalidateAll(): void;
}
